import { useEffect, useRef } from "react";

import { ActiveDocumentInfo, StudioProApi } from "@mendix/extensions-api";
import { DOMAIN_MODEL_DOCUMENT_TYPE, PROJECT_SETTINGS_DOCUMENT_TYPE } from "@src/constants/studioPro";

type UseDependentDocumentChangesProps = {
    studioPro: StudioProApi;
    dependentIds: string[];
    onDependentDocumentsChanged: (changedIds: string[]) => void;
    /** When true, the callback is also invoked with `"projectSettings"` when project settings change. */
    watchProjectSettings?: boolean;
    /** Module names to watch for domain model changes. When a domain model change is detected for a listed module, the callback receives `"domainModel"`. */
    watchDomainModelModules?: string[];
};

export const useDependentDocumentChanges = ({
    studioPro,
    dependentIds,
    onDependentDocumentsChanged,
    watchProjectSettings,
    watchDomainModelModules,
}: UseDependentDocumentChangesProps): void => {
    const callbackRef = useRef(onDependentDocumentsChanged);
    callbackRef.current = onDependentDocumentsChanged;

    const dependentIdsRef = useRef(dependentIds);
    dependentIdsRef.current = dependentIds;

    const watchDomainModelModulesRef = useRef(watchDomainModelModules);
    watchDomainModelModulesRef.current = watchDomainModelModules;

    const watchProjectSettingsRef = useRef(watchProjectSettings);
    watchProjectSettingsRef.current = watchProjectSettings;

    useEffect(() => {
        const handleDocumentChange = ({ documents }: { documents: ActiveDocumentInfo[] }) => {
            const changes: string[] = [];

            for (const doc of documents) {
                if (
                    watchDomainModelModulesRef.current &&
                    doc.documentType === DOMAIN_MODEL_DOCUMENT_TYPE &&
                    doc.moduleName &&
                    watchDomainModelModulesRef.current.includes(doc.moduleName)
                ) {
                    changes.push("domainModel");
                } else if (watchProjectSettingsRef.current && doc.documentType === PROJECT_SETTINGS_DOCUMENT_TYPE) {
                    changes.push("projectSettings");
                } else if (dependentIdsRef.current.includes(doc.documentId)) {
                    changes.push(doc.documentId);
                }
            }

            if (changes.length > 0) {
                callbackRef.current(changes);
            }
        };

        studioPro.app.projectChanges.addEventListener("documentsChanged", handleDocumentChange);

        return () => {
            studioPro.app.projectChanges.removeEventListener("documentsChanged", handleDocumentChange);
        };
    }, [studioPro.app.projectChanges]);
};
